import type { WebcamEntry } from '@/generated/client/worldmonitor/webcam/v1/service_client';

export type OsirisCctvStreamType = 'jpg' | 'hls' | 'mjpeg' | 'mp4' | 'iframe';

export interface OsirisCctvCamera extends WebcamEntry {
  city: string;
  source: string;
  feedUrl?: string;
  streamUrl?: string;
  streamType: OsirisCctvStreamType;
  externalUrl?: string;
}

// Zero-credential CCTV catalogue ported from OSIRIS' public sources
// (src/app/api/cctv). The primary WorldMonitor/Windy catalogue is still used
// whenever available; these entries keep the merged camera workflow usable in
// local/self-hosted installs that have not seeded Redis or configured
// WINDY_API_KEY yet.
//
// 875 cameras / 71 countries, from SkylineWebcams, YouTube Live, APRR + AREA
// (French motorways), nadmorski24.pl, Urząd Miasta Słupsk, national traffic
// authorities (Japan, Czechia, Germany, Serbia, Macedonia, Romania, Slovakia,
// Bulgaria, Taiwan, Thailand) and the Hong Kong
// Transport Department.
//
// Two OSIRIS-specific shapes are normalised at generation time:
//   * OSIRIS routes hotlink-protected Skyline frames through its own
//     /api/cctv/proxy Next route. That route does not exist here, and
//     MapWebcamViewer's safeHttpUrl() drops relative URLs (`new URL()` throws
//     on them), so those are unwrapped back to the absolute CDN URL. Skyline
//     sets hotlink protection, so such a frame may still 403 in the browser —
//     every one of those entries keeps its externalUrl, which the viewer falls
//     back to.
//   * Only ~a third of Skyline poster images actually refresh. Entries without
//     a live frame carry externalUrl alone, putting the viewer into its
//     external-feed state rather than showing a still frozen years ago.
